<style>
:root{--pm-bg:#f6f7f9;--pm-surface:#fff;--pm-surface-soft:#f9fafb;--pm-ink:#101828;--pm-muted:#667085;--pm-subtle:#98a2b3;--pm-border:#e4e7ec;--pm-border-strong:#d0d5dd;--pm-accent:#2563eb;--pm-accent-dark:#1d4ed8;--pm-sidebar:#111827;--pm-sidebar-muted:#9ca3af;--pm-radius:12px}
html,body{background:var(--pm-bg)!important;color:var(--pm-ink)!important}body{font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif!important}.fi-body,.fi-main{background:var(--pm-bg)!important}.fi-sidebar,.fi-sidebar-header,.fi-topbar{background:var(--pm-sidebar)!important;border-color:#1f2937!important;box-shadow:none!important}.fi-sidebar-header{min-height:72px!important}.fi-sidebar-header .fi-logo{color:#fff!important;font-weight:750!important;letter-spacing:-.02em!important}.fi-sidebar-nav{padding:16px 12px!important}.fi-sidebar-group-label{color:#6b7280!important;font-size:10px!important;font-weight:750!important;letter-spacing:.12em!important;text-transform:uppercase!important;padding:16px 10px 7px!important}.fi-sidebar-item{margin:2px 0!important}.fi-sidebar-item-button{border:1px solid transparent!important;border-radius:8px!important;color:var(--pm-sidebar-muted)!important;min-height:40px!important;transition:background .15s,color .15s!important}.fi-sidebar-item-button:hover{background:#1f2937!important;color:#fff!important}.fi-sidebar-item-active .fi-sidebar-item-button{background:#1d4ed8!important;border-color:#2563eb!important;color:#fff!important;box-shadow:none!important}.fi-sidebar-item-icon{color:#9ca3af!important}.fi-sidebar-item-active .fi-sidebar-item-icon{color:#fff!important}.fi-topbar{border-bottom:1px solid #1f2937!important}.fi-header{padding-bottom:22px!important}.fi-header-heading{color:var(--pm-ink)!important;font-size:28px!important;font-weight:750!important;letter-spacing:-.035em!important}.fi-header-subheading{color:var(--pm-muted)!important}.fi-section,.fi-wi-widget,.fi-ta-ctn,.fi-fo-component-ctn,.fi-in-entry-wrp,.fi-modal-window,.fi-dropdown-panel,.fi-user-menu{background:var(--pm-surface)!important;border:1px solid var(--pm-border)!important;border-radius:var(--pm-radius)!important;box-shadow:0 1px 2px rgba(16,24,40,.04)!important;backdrop-filter:none!important}.fi-section-header,.fi-ta-header,.fi-ta-header-cell,.fi-ta-row{border-color:var(--pm-border)!important}.fi-section-header-heading,.fi-section-header-description,.fi-wi-widget-header,.fi-ta-header-cell,.fi-ta-text-item-label{color:var(--pm-ink)!important}.fi-section-header-description,.fi-ta-text-item-description,.fi-wi-widget-header-description{color:var(--pm-muted)!important}.fi-ta-header{background:var(--pm-surface-soft)!important}.fi-ta-row{background:var(--pm-surface)!important}.fi-ta-row:hover{background:#f9fafb!important}.fi-ta-header-cell{color:#667085!important;font-size:11px!important;font-weight:700!important;letter-spacing:.07em!important;text-transform:uppercase!important}.fi-btn{border-radius:8px!important;font-weight:650!important;box-shadow:none!important;min-height:38px!important}.fi-btn-color-primary{background:var(--pm-accent)!important;border:1px solid var(--pm-accent)!important;color:#fff!important}.fi-btn-color-primary:hover{background:var(--pm-accent-dark)!important}.fi-btn:not(.fi-btn-color-primary){background:#fff!important;border:1px solid var(--pm-border-strong)!important;color:#344054!important}.fi-input,.fi-select,.fi-textarea,.fi-fo-text-input,.fi-fo-select,.fi-fo-textarea{background:#fff!important;border-color:var(--pm-border-strong)!important;color:var(--pm-ink)!important;border-radius:8px!important;box-shadow:none!important}.fi-input:focus,.fi-select:focus,.fi-textarea:focus,.fi-fo-text-input:focus,.fi-fo-select:focus,.fi-fo-textarea:focus{border-color:var(--pm-accent)!important;box-shadow:0 0 0 3px rgba(37,99,235,.12)!important}.fi-fo-field-wrp-label,.fi-fo-field-wrp-label span{color:#344054!important;font-weight:650!important}.fi-badge{border-radius:6px!important;font-weight:700!important}.fi-wi-stats-overview-stat{background:var(--pm-surface)!important;border:1px solid var(--pm-border)!important;border-radius:var(--pm-radius)!important;box-shadow:0 1px 2px rgba(16,24,40,.04)!important}.fi-wi-stats-overview-stat-label{color:var(--pm-muted)!important;font-size