.pm-dashboard{max-width:1440px;margin:0 auto;padding-bottom:32px}.pm-dashboard-header{display:flex;align-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:24px}.pm-dashboard-header h1{margin:4px 0 6px;color:var(--pm-ink);font-size:30px;line-height:1.15;font-weight:760;letter-spacing:-.04em}.pm-dashboard-header p{margin:0;color:var(--pm-muted);font-size:14px}.pm-eyebrow{color:#667085!important;font-size:10px!important;font-weight:800!important;letter-spacing:.12em!important;text-transform:uppercase!important}.pm-header-date{display:flex;align-items:center;gap:8px;color:#475467;font-size:13px;font-weight:600;white-space:nowrap}.pm-date-dot{width:7px;height:7px;border-radius:50%;background:#22c55e}.pm-attendance-hero{display:flex;align-items:center;justify-content:space-between;gap:32px;padding:28px 30px;margin-bottom:18px;background:#111827;border:1px solid #1f2937;border-radius:14px;color:#fff;box-shadow:0 8px 24px rgba(16,24,40,.12)}.pm-attendance-hero.is-working{background:#0f172a}.pm-attendance-copy{min-width:0}.pm-status-line{display:flex;align-items:center;gap:8px;color:#9ca3af;font-size:10px;font-weight:800;letter-spacing:.12em}.pm-live-dot{width:7px;height:7px;border-radius:50%;background:#f59e0b}.pm-live-dot.is-live{background:#22c55e;box-shadow:0 0 0 4px rgba(34,197,94,.12)}.pm-attendance-copy h2{margin:8px 0 5px;color:#fff;font-size:25px;line-height:1.2;font-weight:750;letter-spacing:-.025em}.pm-attendance-copy>p{color:#9ca3af!important;margin:0!important;font-size:13px!important}.pm-attendance-meta{display:flex;gap:30px;margin-top:20px}.pm-attendance-meta span{display:flex;flex-direction:column;gap:2px}.pm-attendance-meta strong{color:#fff;font-size:14px;font-weight:700}.pm-attendance-meta small{color:#6b7280;font-size:11px}.pm-attendance-action{display:flex;flex-direction:column;align-items:flex-end;gap:9px;flex:0 0 auto}.pm-clock-button{display:flex;align-items:center;gap:11px;min-width:178px;justify-content:center;padding:13px 18px;border:1px solid #3b82f6;border-radius:9px;background:#2563eb;color:#fff;font-size:14px;font-weight:750;cursor:pointer;transition:transform .15s,background .15s,box-shadow .15s}.pm-clock-button:hover{background:#1d4ed8;box-shadow:0 5px 14px rgba(37,99,235,.25);transform:translateY(-1px)}.pm-clock-button:disabled{opacity:.65;cursor:wait;transform:none}.pm-clock-icon{font-size:21px;line-height:1}.pm-button-arrow{font-size:18px;margin-left:auto}.pm-attendance-action small{color:#6b7280;font-size:10px}.pm-inline-error{margin:-5px 0 18px;padding:10px 12px;border:1px solid #fecdca;background:#fef3f2;color:#b42318;border-radius:8px;font-size:12px}.pm-kpi-grid,.pm-admin-kpi-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:18px}.pm-admin-kpi-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.pm-kpi{display:flex;flex-direction:column;min-height:126px;padding:19px 20px;background:#fff;border:1px solid var(--pm-border);border-radius:12px;text-decoration:none;box-shadow:0 1px 2px rgba(16,24,40,.03);transition:border-color .15s,transform .15s}.pm-kpi:hover{border-color:#cbd5e1;transform:translateY(-1px)}.pm-kpi-label{color:#667085;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em}.pm-kpi strong{margin-top:8px;color:var(--pm-ink);font-size:28px;line-height:1;font-weight:760;letter-spacing:-.035em}.pm-kpi-note{margin-top:auto;color:#98a2b3;font-size:12px}.pm-kpi-primary strong{color:var(--pm-accent)}.pm-content-grid{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,.8fr);gap:18px}.pm-panel{background:#fff;border:1px solid var(--pm-border);border-radius:12px;box-shadow:0 1px 2px rgba(16,24,40,.03);overflow:hidden}.pm-panel-heading{display:flex;align-items:center;justify-content:space-between;padding:20px 22px;border-bottom:1px solid var(--pm-border)}.pm-panel-heading h2,.pm-focus-panel h2{margin:3px 0 0;color:var(--pm-ink);font-size:18px;font-weight:720;letter-spacing:-.02em}.pm-panel-heading a{color:var(--pm-accent);font-size:12px;font-weight:700;text-decoration:none}.pm-panel-heading a span,.pm-text-action span{margin-left:5px}.pm-task-list{padding:2px 0}.pm-task-row{display:flex;align-items:center;gap:13px;padding:15px 22px;border-bottom:1px solid #f0f2f5}.pm-task-row:last-child{border-bottom:0}.pm-task-marker{width:9px;height:9px;border:2px solid #94a3b8;border-radius:50%;flex:0 0 auto}.pm-task-marker.done{border-color:#22c55e;background:#22c55e}.pm-task-main{display:flex;flex-direction:column;gap:3px;min-width:0;flex:1}.pm-task-main strong{overflow:hidden;color:#344054;font-size:13px;font-weight:650;text-overflow:ellipsis;white-space:nowrap}.pm-task-main span{color:#98a2b3;font-size:11px}.pm-priority,.pm-status-chip{padding:5px 8px;border-radius:6px;font-size:10px;font-weight:750;text-transform:uppercase;letter-spacing:.04em;white-space:nowrap}.priority-high{background:#fef3f2;color:#b42318}.priority-medium{background:#fffaeb;color:#b54708}.priority-low{background:#eff8ff;color:#175cd3}.pm-status-chip{background:#f2f4f7;color:#475467}.pm-focus-panel{padding:24px}.pm-focus-panel>p:not(.pm-eyebrow){color:var(--pm-muted);font-size:13px;line-height:1.65}.pm-focus-rule{height:1px;background:var(--pm-border);margin:22px 0}.pm-text-action{color:var(--pm-accent);font-size:12px;font-weight:700;text-decoration:none}.pm-quick-links{display:flex;flex-direction:column;margin-top:18px}.pm-quick-links a{display:flex;justify-content:space-between;padding:13px 0;border-top:1px solid var(--pm-border);color:#344054;text-decoration:none;font-size:13px;font-weight:650}.pm-quick-links a span{color:var(--pm-accent)}.pm-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;min-height:150px;gap:5px;color:#475467;text-align:center}.pm-empty span{color:#98a2b3;font-size:12px}.admin-grid{grid-template-columns:minmax(0,1.7fr) minmax(300px,.8fr)}[x-cloak]{display:none!important}@media(max-width:900px){.pm-dashboard-header,.pm-attendance-hero{align-items:flex-start;flex-direction:column}.pm-attendance-action{align-items:stretch;width:100%}.pm-clock-button{width:100%}.pm-admin-kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pm-content-grid{grid-template-columns:1fr}}@media(max-width:640px){.pm-dashboard-header h1{font-size:25px}.pm-header-date{display:none}.pm-kpi-grid,.pm-admin-kpi-grid{grid-template-columns:1fr}.pm-attendance-hero{padding:22px}.pm-attendance-meta{gap:18px;flex-wrap:wrap}.pm-task-row{padding:14px 16px}.pm-panel-heading{padding:17px 16px}.pm-focus-panel{padding:20px}}
